-- KIA PIECE additive garage schema migration. Apply on development branch first.
CREATE TABLE IF NOT EXISTS garages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT, email TEXT, address JSONB NOT NULL DEFAULT '{}'::jsonb, timezone TEXT NOT NULL DEFAULT 'Indian/Antananarivo', currency CHAR(3) NOT NULL DEFAULT 'MGA', is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());

ALTER TABLE users ADD COLUMN IF NOT EXISTS garage_id UUID REFERENCES garages(id) ON DELETE SET NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE products ADD COLUMN IF NOT EXISTS purchase_price NUMERIC(12,2) CHECK (purchase_price IS NULL OR purchase_price >= 0);
ALTER TABLE products ADD COLUMN IF NOT EXISTS tax_rate NUMERIC(5,2) CHECK (tax_rate IS NULL OR (tax_rate >= 0 AND tax_rate <= 100));
ALTER TABLE products ADD COLUMN IF NOT EXISTS warranty_months INTEGER CHECK (warranty_months IS NULL OR warranty_months >= 0);
ALTER TABLE products ADD COLUMN IF NOT EXISTS origin TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS reserved_quantity INTEGER NOT NULL DEFAULT 0 CHECK (reserved_quantity >= 0);
ALTER TABLE products ADD COLUMN IF NOT EXISTS minimum_stock INTEGER NOT NULL DEFAULT 0 CHECK (minimum_stock >= 0);
ALTER TABLE products ADD COLUMN IF NOT EXISTS garage_id UUID REFERENCES garages(id) ON DELETE SET NULL;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS displacement_cc INTEGER CHECK (displacement_cc IS NULL OR displacement_cc > 0);
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS fuel_type TEXT;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS version TEXT;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS vin TEXT;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS registration_number TEXT;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS garage_id UUID REFERENCES garages(id) ON DELETE SET NULL;
ALTER TABLE product_compatibility ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'to_verify' CHECK (status IN ('confirmed','to_verify','incompatible'));
ALTER TABLE product_compatibility ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE product_compatibility ADD COLUMN IF NOT EXISTS confidence NUMERIC(5,2) CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 100));
ALTER TABLE product_compatibility ADD COLUMN IF NOT EXISTS verified_by UUID REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE product_compatibility ADD COLUMN IF NOT EXISTS verified_at TIMESTAMPTZ;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','partial','paid','refunded','partially_refunded'));
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_method TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_status TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMPTZ;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS garage_id UUID REFERENCES garages(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS user_role_assignments (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('seller','mechanic','storekeeper','accountant')), garage_id UUID REFERENCES garages(id) ON DELETE CASCADE, granted_by UUID REFERENCES users(id) ON DELETE SET NULL, granted_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role,garage_id));
CREATE TABLE IF NOT EXISTS customer_vehicles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, vehicle_id UUID REFERENCES vehicles(id) ON DELETE SET NULL, registration_number TEXT, vin TEXT, make TEXT NOT NULL DEFAULT 'Kia', model TEXT NOT NULL, model_year SMALLINT, engine TEXT, fuel_type TEXT, displacement_cc INTEGER, mileage_km INTEGER CHECK (mileage_km IS NULL OR mileage_km >= 0), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_references (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, reference TEXT NOT NULL, reference_type TEXT NOT NULL CHECK (reference_type IN ('oem','alternative','superseded','manufacturer')), manufacturer TEXT, status TEXT NOT NULL DEFAULT 'to_verify' CHECK (status IN ('confirmed','to_verify','obsolete')), source TEXT, verified_by UUID REFERENCES users(id) ON DELETE SET NULL, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(reference,reference_type,product_id));
CREATE TABLE IF NOT EXISTS product_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, image_url TEXT NOT NULL, alt_text TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_primary BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), garage_id UUID REFERENCES garages(id) ON DELETE SET NULL, code TEXT NOT NULL, name TEXT NOT NULL, store_name TEXT, aisle TEXT, shelf TEXT, bin TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(garage_id,code));
ALTER TABLE products ADD COLUMN IF NOT EXISTS location_id UUID REFERENCES inventory_locations(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS inventory_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT, location_id UUID REFERENCES inventory_locations(id) ON DELETE SET NULL, movement_type TEXT NOT NULL CHECK (movement_type IN ('receipt','sale','reservation','release','return','damage','loss','adjustment','repair_use','transfer_in','transfer_out')), quantity INTEGER NOT NULL CHECK (quantity <> 0), unit_cost NUMERIC(12,2), reason TEXT NOT NULL, reference_type TEXT, reference_id UUID, document_number TEXT, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_reservations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT, order_id UUID REFERENCES orders(id) ON DELETE CASCADE, quantity INTEGER NOT NULL CHECK (quantity > 0), status TEXT NOT NULL DEFAULT 'reserved' CHECK (status IN ('reserved','consumed','released','expired')), expires_at TIMESTAMPTZ, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), garage_id UUID REFERENCES garages(id) ON DELETE SET NULL, name TEXT NOT NULL, contact_name TEXT, email TEXT, phone TEXT, address JSONB NOT NULL DEFAULT '{}'::jsonb, payment_terms TEXT, lead_time_days INTEGER CHECK (lead_time_days IS NULL OR lead_time_days >= 0), notes TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT, order_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','partially_received','received','cancelled')), ordered_at TIMESTAMPTZ, expected_at TIMESTAMPTZ, received_at TIMESTAMPTZ, currency CHAR(3) NOT NULL DEFAULT 'MGA', subtotal NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0), notes TEXT, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_order_id UUID NOT NULL REFERENCES supplier_orders(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id) ON DELETE SET NULL, reference TEXT, description TEXT NOT NULL, quantity_ordered INTEGER NOT NULL CHECK (quantity_ordered > 0), quantity_received INTEGER NOT NULL DEFAULT 0 CHECK (quantity_received >= 0), unit_cost NUMERIC(12,2) NOT NULL CHECK (unit_cost >= 0));
CREATE INDEX IF NOT EXISTS inventory_movements_product_created_idx ON inventory_movements(product_id,created_at DESC);
CREATE INDEX IF NOT EXISTS stock_reservations_product_status_idx ON stock_reservations(product_id,status,expires_at);
CREATE INDEX IF NOT EXISTS customer_vehicles_customer_idx ON customer_vehicles(customer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS supplier_orders_supplier_idx ON supplier_orders(supplier_id,created_at DESC);
CREATE INDEX IF NOT EXISTS product_references_lookup_idx ON product_references(reference);
CREATE INDEX IF NOT EXISTS products_low_stock_idx ON products(stock_quantity,minimum_stock) WHERE is_active=true;
